export interface Customer {
  yearsWithMHPCO: number;
}

export interface Item {
  type: string;
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export type Step = QuoteStep;

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export interface QuoteResult {
  premium: number;
}

export interface ScenarioResult {
  results: QuoteResult[];
}

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_PERCENT = 10;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

/**
 * Premiums are accumulated in hundredths of a G so that percentage modifiers
 * stay exact; only the final amount is rounded (in the MHPCO's favour).
 */
function quotePremium(items: Item[]): number {
  const hundredths = items.reduce(
    (sum, item) => sum + BASE_PREMIUMS[item.type] * (100 + FIRST_INSURANCE_PERCENT),
    0,
  );
  return Math.ceil(hundredths / 100 + PROCESSING_FEE);
}

export function runScenario(scenario: Scenario): ScenarioResult {
  return { results: scenario.steps.map((step) => ({ premium: quotePremium(step.items) })) };
}

