export interface Customer {
  yearsWithMHPCO: number;
}

export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export type Step = QuoteStep;

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export interface QuoteResult {
  premium: number;
}

export interface ScenarioResult {
  results: QuoteResult[];
}

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_PERCENT = 10;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;

function countByType(items: Item[]): Map<string, number> {
  const counts = new Map<string, number>();
  for (const item of items) {
    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
  }
  return counts;
}

/** Base premium for `count` alike components: a block of exactly 3 is discounted. */
function componentsBasePremium(type: string, count: number): number {
  return count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * BASE_PREMIUMS[type];
}

function policyBasePremium(items: Item[]): number {
  let base = 0;
  for (const [type, count] of countByType(items)) {
    base += COMPONENT_TYPES.has(type)
      ? componentsBasePremium(type, count)
      : count * BASE_PREMIUMS[type];
  }
  return base;
}

/**
 * Premiums are accumulated in hundredths of a G so that percentage modifiers
 * stay exact; only the final amount is rounded (in the MHPCO's favour).
 */
function quotePremium(items: Item[]): number {
  const hundredths = policyBasePremium(items) * (100 + FIRST_INSURANCE_PERCENT);
  return Math.ceil(hundredths / 100 + PROCESSING_FEE);
}

export function runScenario(scenario: Scenario): ScenarioResult {
  return { results: scenario.steps.map((step) => ({ premium: quotePremium(step.items) })) };
}

