import { describe, it, expect } from "vitest";
import { runScenario, type Item } from "./claim-office.js";

/** Premium for a single quote of `items`, for a customer with `yearsWithMHPCO`. */
function premiumFor(items: Item[], yearsWithMHPCO = 0): number {
  const { results } = runScenario({
    customer: { yearsWithMHPCO },
    steps: [{ op: "quote", items }],
  });
  return (results[0] as { premium: number }).premium;
}

describe("MHPCO Claim Office", () => {
  // --- Quote: simplest cases ---
  it("empty item list → premium 5 G (only the processing fee)", () => {
    expect(premiumFor([])).toBe(5);
  });
  it("single sword, new customer → premium 115 G (100 base + 10 first insurance + 5 fee)", () => {
    expect(premiumFor([{ type: "sword" }])).toBe(115);
  });
  it("single amulet, new customer → premium 71 G (60 base + 6 first insurance + 5 fee)", () => {
    expect(premiumFor([{ type: "amulet" }])).toBe(71);
  });
  it("single staff, new customer → premium 93 G (80 base + 8 first insurance + 5 fee)", () => {
    expect(premiumFor([{ type: "staff" }])).toBe(93);
  });
  it("single potion, new customer → premium 49 G (40 base + 4 first insurance + 5 fee)", () => {
    expect(premiumFor([{ type: "potion" }])).toBe(49);
  });

  // --- Components and building blocks ---
  it("2 runes → 50 G base premium (→ 50×1.1 + 5 fee = 60 G)", () => {
    expect(premiumFor([{ type: "rune" }, { type: "rune" }])).toBe(60);
  });
  it("3 runes → 60 G base premium (block applies) (→ 60×1.1 + 5 = 71 G)", () => {
    expect(premiumFor([{ type: "rune" }, { type: "rune" }, { type: "rune" }])).toBe(71);
  });
  it("4 runes → 100 G base premium (no block — block requires exactly 3) (→ 100×1.1 + 5 = 115 G)", () => {
    expect(premiumFor(Array.from({ length: 4 }, () => ({ type: "rune" })))).toBe(115);
  });
  it("7 runes → 175 G base premium (→ 175×1.1 + 5 = 197.5 → 198 G)", () => {
    expect(premiumFor(Array.from({ length: 7 }, () => ({ type: "rune" })))).toBe(198);
  });
  it("2 runes + 1 moonstone → 75 G base premium (no block: different types) (→ 75×1.1 + 5 = 87.5 → 88 G)", () => {
    expect(premiumFor([{ type: "rune" }, { type: "rune" }, { type: "moonstone" }])).toBe(88);
  });
  it("3 runes + 3 moonstones → 120 G base premium (two separate blocks) (→ 120×1.1 + 5 = 137 G)", () => {
    const items = [
      ...Array.from({ length: 3 }, () => ({ type: "rune" })),
      ...Array.from({ length: 3 }, () => ({ type: "moonstone" })),
    ];
    expect(premiumFor(items)).toBe(137);
  });

  // --- Premium modifiers in isolation ---
  it("cursed sword adds 50 % risk surcharge → 50 G on top of 100 G base premium (100 + 50 curse + 10 first insurance + 5 fee = 165 G)", () => {
    expect(premiumFor([{ type: "sword", cursed: true }])).toBe(165);
  });
  it("sword with exactly enchantment 5 → high-enchantment surcharge 30 G applies (100 + 30 + 10 + 5 = 145 G)", () => {
    expect(premiumFor([{ type: "sword", enchantment: 5 }])).toBe(145);
  });
  it.todo("sword with enchantment 4 → no high-enchantment surcharge");
  it.todo("cursed sword with exactly enchantment 5 → both surcharges apply (100 + 50 + 30)");
  it.todo("customer with exactly 2 years with MHPCO → 20 % loyalty discount applies");
  it.todo("customer with 1 year with MHPCO → no loyalty discount");
  it.todo("first insurance carries a 10 % initial assessment surcharge");
  it.todo("second contract receives a 15 % follow-up discount on the policy base premium");

  // --- Modifier scope on multi-item policies ---
  it.todo("cursed sword + plain amulet → policy base 160 G, curse adds 50 G (only on sword) → 210 G before further modifiers and fee");
  it.todo("policy-wide modifiers apply to the sum of item base premiums, fee added at the very end");

  // --- Rounding ---
  it.todo("premium calculation yielding 197.5 G → final premium 198 G (rounded up)");
  it.todo("payout calculation yielding 350.5 G → final payout 350 G (rounded down)");
  it.todo("intermediate amounts are kept as fractions; only the final amount is rounded");

  // --- Claim: standard reimbursement ---
  it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G");
  it.todo("damage to a rune (value 250 G), damage 200 G → payout 100 G (no special clause)");

  // --- Claim: special clauses ---
  it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % first, then deductible)");
  it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G (full reimbursement, then deductible)");
  it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (50 % rule wins, then deductible)");
  it.todo("dragon-material sword with exactly enchantment 8, damage 1000 G → payout 400 G");

  // --- Deductible per damage event ---
  it.todo("dragon attack damages sword (500 G) and amulet (300 G) → payout 600 G (deductible once per damaged item)");

  // --- Multiple items of the same type ---
  it.todo("policy covers two swords → insurance sum 2000 G, cap 4000 G");
  it.todo("two sword damage entries against two insured swords → each entry has its own deductible");
  it.todo("more damage entries of a type than insured items → CLI exits non-zero, whole claim rejected");

  // --- Cap ---
  it.todo("policy covers a sword and an amulet → insurance sum 1600 G, cap 3200 G");
  it.todo("cursed sword (premium 165 G) → cap 2000 G (premium modifiers do not raise the cap)");
  it.todo("policy covers a sword and 3 runes → insurance sum 1750 G (block discount affects premium only)");
  it.todo("sword insured (cap 2000 G), first claim of 1500 G → payout 1400 G, remainingCap 600 G");
  it.todo("sword insured (cap 2000 G), second claim of 1500 G → payout 600 G, remainingCap 0 G");

  // --- Integration examples ---
  it.todo("newcomer (0 years) with a cursed sword (steel, enchantment 3) → premium 165 G");
  it.todo("3-year customer's second quote, cursed sword enchantment 7 → premium 160 G (first insurance still applies per item)");

  // --- Error cases ---
  it.todo("quote with an unknown item type → CLI exits non-zero, error on stderr, no results on stdout");
  it.todo("claim referencing an item not part of the policy → CLI exits non-zero with error on stderr");
  it.todo("claim referencing an unknown item type → CLI exits non-zero with error on stderr");
  it.todo("claim with a damage entry of amount -200 → CLI exits non-zero with error on stderr");

  // --- CLI ---
  it.todo("CLI reads the schema example scenario from stdin and writes {results:[{premium},{payout,remainingCap}]} to stdout");
});

